<?php
require __DIR__.'/app/bootstrap.php';
$userId=require_auth();$pdo=db();$messageService=new TravelMessageService($pdo);$matchService=new TravelMatchService($pdo);$mineProfile=$matchService->profile($userId);if($mineProfile&&!empty($mineProfile['enabled']))$matchService->touchActivity($userId);$matchId=(int)($_GET['match']??$_POST['match']??0);$match=$messageService->match($matchId,$userId);
if(!$match||($match['status']??'')!=='active'){http_response_code(404);exit('Travel Match conversation not available.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');if($action==='block'){$matchService->act($userId,(int)$match['partner_id'],'block');flash('success','Travel Match blocked and the conversation has been closed.');redirect('match-contacts.php');}if($action==='unmatch'){$matchService->unmatch($userId,$matchId,(string)($_POST['unmatch_reason']??'not_interested'));flash('success','Travel Match ended. The conversation is closed, but no safety report was created.');redirect('match-contacts.php');}}
$partner=$matchService->profile((int)$match['partner_id']);if(!$partner){http_response_code(404);exit('Travel Match profile not available.');}
$messages=$messageService->messages($matchId,$userId,0,100);$lastId=$messages?(int)end($messages)['id']:0;$comp=$matchService->compatibility($userId,(int)$match['partner_id']);$engagement=new MatchEngagementService($pdo);$icebreakers=$engagement->icebreakers($matchId,$userId,4);$streak=$engagement->streak($matchId,$userId);$starter=trim((string)($_GET['starter']??''));if(strlen($starter)>500)$starter=substr($starter,0,500);$success=flash('success');$error=flash('error');$title='Message '.($partner['display_name']?:'Travel Match');require __DIR__.'/partials/header.php';
$reactionLabels=['same'=>'Same','laugh'=>'😂','love'=>'♥','red_flag'=>'Red flag'];
?>
<section class="match-chat-page"><div class="shell chat-shell">
