<div class="chat-match-tools"><a href="<?=e(app_url('match-space.php?match='.$matchId))?>"><strong><?=$streak['current']?>-day shared streak</strong><span>Daily question, discoveries & games →</span></a></div><div class="chat-icebreakers"><span>Vacation Brain icebreakers</span><div><?php foreach($icebreakers as $line):?><button type="button" data-chat-starter="<?=e($line)?>"><?=e($line)?></button><?php endforeach;?></div></div>
