<dialog class="report-message-modal" data-report-dialog><form method="dialog" class="report-message-card"><button class="dialog-close" value="cancel" aria-label="Close">×</button><span class="eyebrow">Conversation Safety</span><h2>Report this message?</h2><p class="muted">Reporting the message will also block this Travel Match and close the conversation.</p><input type="hidden" data-report-message-id><label>Reason<select data-report-reason><option value="harassment">Harassment</option><option value="spam">Spam</option><option value="fake_profile">Fake profile</option><option value="unsafe_behavior">Unsafe behavior</option><option value="underage_concern">Possible underage user</option><option value="other">Other</option></select></label><label>Details<textarea data-report-details rows="3" maxlength="1000" placeholder="Optional details"></textarea></label><button class="button primary" value="cancel" type="button" data-submit-report>Report & block</button></form></dialog>
</div></section>
